{
  "technical_and_design_decisions": [
    "Treat U4 and U5 as a single user story since they are exact duplicates; the implementation effort is shared.",
    "U2 is explicitly scoped as a 'Spike' (investigation, design, and documentation only) — no production code is to be delivered for it in this increment.",
    "U3 is a performance investigation activity (profiling, bottleneck identification, documentation) — not a code change request.",
    "U6 and U7 are functionally parallel (override of two different external locations) and will share the configuration-property plumbing design.",
    "Use Spring XD's existing module SPI (Stream/Job processors) for the RxJava module to avoid creating a parallel module system.",
    "Reuse the existing distributed-resource-loader pattern in Spring XD for HDFS-backed module storage, extending it rather than introducing a new storage layer.",
    "Add an administrative endpoint (admin server) and a SparkLauncher control hook for the U8 'stop job' capability, instead of inventing a new control plane.",
    "Single-developer delivery: the work is performed end-to-end by one engineer, so no handoff or coordination overhead is included.",
    "All efforts are in work-hours (focused, productive development time) rather than elapsed calendar duration."
  ],
  "assumptions": [
    "The runtime in question is Spring XD (eXtreme Data), as indicated by terms like 'admin and container servers', 'module uber-jar', 'XD runtime', and 'Spark job'.",
    "The target environment is Java 17+ as per the Spring Framework 6.0 baseline stated in the specification preamble.",
    "A reusable HDFS client (Hadoop FileSystem API) is already available on the classpath via existing XD/YARN integration; no new Hadoop dependency is required.",
    "Cloud Foundry (CF) configuration overrides for U6/U7 will be implemented as Spring `@PropertySource` / environment variable bindings rather than via a CF-specific service binding.",
    "Performance tooling (YourKit / JFR / async-profiler) is available and licensed for the developer performing U3.",
    "Unit and integration tests are scoped to the new functionality only; existing test suites are not regenerated.",
    "The 'flexible RxJava module' (U1) means an XD processor module wrapping an RxJava `Flowable`/`Observable` — not a full reactive rewrite of XD internals.",
    "U8's 'clean-up resources' means releasing the Spark application context, cancelling running SparkContexts, and unregistering the module entry — full resource reclamation is assumed to be handled by the underlying Spark framework.",
    "No new UI/DSL is built for U2 in this increment; the spike only documents the future scope."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Architecture, design, and project setup",
      "activity_description": "Set up the development environment, review existing XD module SPI and admin/container server code paths, produce a high-level design covering HDFS storage, RxJava processor, Spark stop, and CF/YARN overrides."
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 — RxJava processor module",
      "activity_description": "Implement a Spring XD processor module that wraps an RxJava Flowable/Observable, including message conversion, back-pressure handling, error channels, and module metadata/registration."
    },
    {
      "activity_id": "A3",
      "activity_name": "U2 — ACL spike (investigation, design, documentation)",
      "activity_description": "Review customer use cases for per-user resource ACLs, identify the approach that best fits the XD runtime, scope the DSL and UI work, and document next steps and phases. No production implementation."
    },
    {
      "activity_id": "A4",
      "activity_name": "U3 — High CPU startup time investigation",
      "activity_description": "Profile admin and container server startup, identify the bottlenecks (classpath scanning, module registration, bean wiring, etc.), document the root causes, and provide a pros/cons list of remediation options."
    },
    {
      "activity_id": "A5",
      "activity_name": "U4/U5 — HDFS storage for custom module uber-jar",
      "activity_description": "Extend the module registration/distribution mechanism so the custom module uber-jar is written to and read from HDFS, supporting reliable re-install under HA failure scenarios (idempotent publish, atomic rename, retries)."
    },
    {
      "activity_id": "A6",
      "activity_name": "U6 — Override HDFS location (Cloud Foundry)",
      "activity_description": "Add a configurable property (env var / Spring property) to override the HDFS location used for storing and retrieving the custom module uber-jar, including CF deployment documentation."
    },
    {
      "activity_id": "A7",
      "activity_name": "U7 — Override YARN config location",
      "activity_description": "Add a configurable property to override the YARN configuration location used for module storage and retrieval, with the same override pattern as U6."
    },
    {
      "activity_id": "A8",
      "activity_name": "U8 — Stop existing Spark job and clean up resources",
      "activity_description": "Implement a stop-Job operation on the admin REST API and CLI that signals the running Spark driver, cancels the SparkContext, and triggers module/resource cleanup at completion."
    },
    {
      "activity_id": "A9",
      "activity_name": "Unit testing",
      "activity_description": "Write JUnit/Mockito unit tests for the new RxJava module, HDFS storage logic, config-override wiring, Spark stop command, and supporting services."
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration testing",
      "activity_description": "Build end-to-end integration tests covering: deploying an RxJava module, publishing a module to HDFS, overriding the HDFS/YARN locations, and stopping a Spark job mid-flight with resource cleanup."
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation",
      "activity_description": "Update the XD reference guide: RxJava processor usage, HDFS uber-jar storage, configuration override properties, stop-job API, and the U2 spike design notes."
    }
  ],
  "reported_total": {
    "most_likely_effort": 168
  }
}
